import type { BatchControl, BatchResult, ControlResult, DownloadConnection, DownloadControl, DownloadQueue, DownloadSource, SourceQueue } from "./download-types";
import type { WidgetServerContext } from "@homarr/widget-sdk/server";
import { callWidgetIntegration, defineWidgetServer, getWidgetServerContext } from "@homarr/widget-sdk/server";

const declared:DownloadConnection[] = ["client","secondary"];
const allowed = new Set(["pause","resume","pauseItem","resumeItem","deleteItem"]);
async function sources(context:WidgetServerContext):Promise<DownloadSource[]> {
  const {bindingNames,options} = await getWidgetServerContext(context);
  return declared.filter((connection) => bindingNames.includes(connection)).map((connection) => {
    let label = options.primaryLabel;
    if (connection === "secondary") label = options.secondaryLabel;
    if (typeof label !== "string" || !label.trim()) label = connection === "client" ? "Primary client" : "Second client";
    return {connection,label:String(label)};
  });
}
async function source(context:WidgetServerContext,connection:DownloadConnection) {
  const result = (await sources(context)).find((candidate) => candidate.connection === connection);
  if (!result) throw new Error("Choose a declared, bound download client");
  return result;
}
async function queue(context:WidgetServerContext,connection:DownloadConnection):Promise<SourceQueue> {
  const selected = await source(context,connection);
  const result = await callWidgetIntegration<DownloadQueue>(context,{connection,capability:"downloads.queue",input:{limit:100}});
  return {...selected,data:result.data};
}
async function control(context:WidgetServerContext,input:DownloadControl):Promise<ControlResult> {
  if (!allowed.has(input?.operation)) throw new Error("Unknown download operation");
  await source(context,input.connection);
  if (input.operation === "pause" || input.operation === "resume") {
    await callWidgetIntegration(context,{connection:input.connection,capability:`downloads.${input.operation}`,input:{}});
  } else {
    if (typeof input.itemId !== "string" || !input.itemId) throw new Error("Choose a download from this client");
    const current = await queue(context,input.connection);
    const item = current.data.items.find((candidate) => candidate.id === input.itemId);
    if (!item) throw new Error("The download is no longer in this client's queue; refresh and try again");
    // Resolve the canonical item in the selected client. Never trust a browser-supplied client index or item object.
    await callWidgetIntegration(context,{connection:input.connection,capability:`downloads.${input.operation}`,input:{item,fromDisk:false}});
  }
  return {connection:input.connection,operation:input.operation,ok:true};
}
export default defineWidgetServer({
  sources: (_input:unknown,context) => sources(context),
  queue: (input:{connection:DownloadConnection},context) => queue(context,input.connection),
  control: (input:DownloadControl,context) => control(context,input),
  controlBatch: async (input:BatchControl,context):Promise<BatchResult> => {
    if (!["pause","resume"].includes(input?.operation)) throw new Error("Batch actions support pause or resume only");
    if (!Array.isArray(input.connections) || !input.connections.length || input.connections.length > 2 || new Set(input.connections).size !== input.connections.length)
      throw new Error("Choose one or two different download clients");
    const available = await sources(context);
    if (input.connections.some((connection) => !available.some((candidate) => candidate.connection === connection)))
      throw new Error("Every batch target must be a declared, bound client");
    const results = await Promise.all(input.connections.map(async (connection):Promise<ControlResult> => {
      try { return await control(context,{connection,operation:input.operation}); }
      catch (error) { return {connection,operation:input.operation,ok:false,error:error instanceof Error ? error.message : String(error)}; }
    }));
    const succeeded = results.filter((result) => result.ok).length;
    return {results,succeeded,failed:results.length-succeeded};
  },
});

