import type { WidgetServerHandler } from "@homarr/widget-sdk/server";
import { defineWidgetServer } from "@homarr/widget-sdk/server";
import rack from "./rack-server.ts";
import downloads from "./downloads-server.ts";
import media from "./media-server.ts";
const prefix = (name:string, handlers:Record<string,WidgetServerHandler<never>>) => Object.fromEntries(Object.entries(handlers).map(([key, handler]) => [`${name}.${key}`, handler]));
export default defineWidgetServer({...prefix("rack", rack), ...prefix("downloads", downloads), ...prefix("media", media)});

