export type DownloadConnection = "client" | "secondary";
export type DownloadOperation = "pause" | "resume" | "pauseItem" | "resumeItem" | "deleteItem";
export interface DownloadItem {
  id:string;name:string;state:string;progress:number;downSpeed?:number;
  index:number;type:"torrent"|"usenet"|"miscellaneous";size:number;time:number;
}
export interface DownloadQueue {data:{items:DownloadItem[];status:{paused:boolean;rates:{down:number;up?:number}}}}
export interface DownloadSource {connection:DownloadConnection;label:string}
export interface SourceQueue extends DownloadSource {data:DownloadQueue["data"]}
export interface DownloadControl {connection:DownloadConnection;operation:DownloadOperation;itemId?:string}
export interface BatchControl {connections:DownloadConnection[];operation:"pause"|"resume"}
export interface ControlResult {connection:DownloadConnection;operation:DownloadOperation;ok:boolean;error?:string}
export interface BatchResult {results:ControlResult[];succeeded:number;failed:number}
export interface DownloadOptions {primaryLabel:string;secondaryLabel:string}

